      hu: ["Patagónia legmagasabb hegycsúcsa 4709 méteres magassággal.", "Neuquén tartomány északi részén, a Cordillera del Viento vonulatban fekszik.", "Neve a mapuche nyelvből származik, jelentése remegés.", "Híres a Las Olletas geotermikus terület gejzírjeiről.", "Geológiailag egy hatalmas vulkáni komplexum részének tekintik.", "Európaiak általi első megmászása csak 1903-ban történt meg.", "Vulkáni eredete ellenére nincs klasszikus kráterformája."],
