      en: ["Highest mountain in Patagonia, with an elevation of 4,709 meters.", "Located in the Cordillera del Viento in Neuquén province.", "Its name means 'to tremble and grumble' in the Mapuche language.", "Home to Argentina's only geysers in the Las Olletas area.", "First climbed by Europeans in 1903.", "Part of a vast, inactive volcanic complex.", "A major site for geothermal studies in the region."],
