    image: "/poi-images/cerro-champaqui-relief-v2.webp",
    description: {
      de: "Der höchste Gipfel der Sierras de Córdoba, bekannt für seine rauen Granitfelsen und kleinen Bergseen auf der Hochebene.",
      hu: "A Sierras de Córdoba legmagasabb csúcsa, amely a fennsíkon található durva gránitszikláiról és kis hegyi tavairól ismert.",
      ro: "Cel mai înalt vârf din Sierras de Córdoba, cunoscut pentru stâncile aspre de granit și micile lacuri montane de pe platou.",
      en: "The highest peak in the Sierras de Córdoba, known for its rough granite rocks and small mountain lakes on the plateau.",
      es: "La cumbre más alta de las Sierras de Córdoba, conocida por sus rocas de granito rugosas y pequeños lagos de montaña en la meseta.",
      pt: "O pico mais alto das Sierras de Córdoba, conhecido por suas rochas de granito rugosas e pequenos lagos de montanha no planalto.",
      fr: "Le plus haut sommet des Sierras de Córdoba, connu pour ses rochers de granit escarpés et ses petits lacs de montagne sur le plateau.",
    },
    facts: {
      de: ["Bietet von seinem 2790 Meter hohen Gipfel weite Ausblicke.", "Ist ein sehr beliebtes Ziel für mehrtägige Trekkingtouren."],
      hu: ["2790 méteres csúcsáról széles panoráma nyílik.", "Nagyon népszerű célpont a többnapos túrázók körében."],
      ro: ["Oferă priveliști vaste de la vârful său de 2790 de metri.", "Este o destinație foarte populară pentru drumeții de mai multe zile."],
      en: ["Offers vast views from its 2790-meter summit.", "It is a highly popular destination for multi-day trekking tours."],
      es: ["Ofrece amplias vistas desde su cumbre de 2.790 metros de altura.", "Es un destino muy popular para rutas de trekking de varios días."],
      pt: ["Oferece vistas amplas a partir do seu cume de 2.790 metros de altura.", "É um destino muito popular para trilhas de trekking de vários dias."],
      fr: ["Offre des vues imprenables depuis son sommet de 2 790 mètres.", "C'est une destination très prisée pour les randonnées de plusieurs jours."],
    },
    descriptionAdvanced: {
      de: "Der Cerro Champaquí ist mit 2790 Metern die höchste Erhebung der Sierras de Córdoba und das Wahrzeichen der Region Traslasierra. Er liegt in der Kette der Sierras Grandes und bildet eine natürliche Grenze zwischen den Tälern Valle de Calamuchita und Valle de Traslasierra. Der Gipfel ist durch ein weites Plateau geprägt, auf dem sich ein kleiner, kristallklarer See befindet, der dem Berg seinen Namen gab (Champaquí bedeutet in der Sprache der Comechingones Wasser im Gras). Der Aufstieg zum Champaquí ist eine der beliebtesten Trekkingtouren Argentiniens und kann von verschiedenen Seiten unternommen werden. Vom Gipfel aus bietet sich bei gutem Wetter ein fantastischer Blick über die gesamte Provinz Córdoba. Die Flora ist geprägt von Tabaquillo-Wäldern und weiten Grasflächen, die vielen Greifvögeln wie dem Andenkondor als Jagdrevier dienen.",
      hu: "A Cerro Champaquí 2790 méterével a Sierras de Córdoba legmagasabb pontja és a Traslasierra régió jelképe. A Sierras Grandes láncolatában fekszik, és természetes határt képez a Valle de Calamuchita és a Valle de Traslasierra völgyek között. A csúcsot egy széles fennsík jellemzi, amelyen egy kis, kristálytiszta tó található – ez adta a hegy nevét is (a Champaquí a comechingónok nyelvén füves vizet jelent). A Champaquí megmászása Argentína egyik legnépszerűbb túraútvonala, amely több irányból is megközelíthető. A csúcsról jó időben fantasztikus kilátás nyílik az egész Córdoba tartományra. A flórát tabaquillo erdők és kiterjedt füves területek jellemzik, amelyek számos ragadozó madárnak, például az andoki kondornak szolgálnak vadászterületül.",
      ro: "Cerro Champaquí este cel mai înalt vârf din provincia Córdoba, atingând 2.790 de metri, fiind considerat 'acoperișul' regiunii Sierras de Córdoba. Situat în masivul Sierras Grandes, acesta este o destinație de pelerinaj pentru mii de iubitori de trekking care urcă spre vârful său pentru a se bucura de o panoramă de 360 de grade asupra văilor Traslasierra și Calamuchita. Versantul său vestic este abrupt și stâncos, în timp ce cel estic are pante mai line. O caracteristică unică a vârfului este existența unei mici lagune de apă dulce care dă numele muntelui. Regiunea din jur este o rezervație hidrologică vitală, adăpostind specii native precum condorul andin și păduri de tabaquillo. Ascensiunea pe Champaquí este un ritual clasic al aventurii argentiniene, simbolizând conexiunea cu natura montană centrală.",
      en: "Cerro Champaquí is the highest peak in the province of Córdoba, reaching 2,790 meters, and is considered the 'roof' of the Sierras de Córdoba region. Located in the Sierras Grandes massif, it is a pilgrimage destination for thousands of trekking enthusiasts who ascend to its summit to enjoy a 360-degree panorama of the Traslasierra and Calamuchita valleys. Its western slope is steep and rocky, while the eastern slope has gentler inclines. A unique feature of the summit is the existence of a small freshwater lagoon that gives the mountain its name. The surrounding region is a vital hydrological reserve, hosting native species such as the Andean condor and tabaquillo forests. The ascent of Champaquí is a classic ritual of Argentine adventure, symbolizing the connection with the central mountain nature.",
      es: "El Cerro Champaquí, con 2.790 metros, es la mayor elevación de las Sierras de Córdoba y el emblema de la región de Traslasierra. Se encuentra en la cadena de las Sierras Grandes y constituye un límite natural entre los valles de Calamuchita y Traslasierra. La cumbre se caracteriza por una amplia meseta donde se encuentra una pequeña laguna de agua cristalina que dio nombre a la montaña (Champaquí significa en lengua comechingón agua en la hierba). El ascenso al Champaquí es una de las rutas de trekking más populares de Argentina y puede realizarse desde diferentes vertientes. Desde la cumbre se ofrece, con buen tiempo, una vista fantástica de toda la provincia de Córdoba. La flora destaca por los bosques de tabaquillo y amplios pastizales que sirven de zona de caza para muchas aves rapaces como el cóndor andino.",
      pt: "O Cerro Champaquí, com 2.790 metros, é o ponto mais alto das Sierras de Córdoba e o símbolo da região de Traslasierra. Localiza-se na cordilheira das Sierras Grandes e forma uma fronteira natural entre os vales de Calamuchita e Traslasierra. O cume é caracterizado por um amplo planalto onde se encontra um pequeno lago de águas cristalinas que deu nome à montanha (Champaquí significa água na grama na língua dos Comechingones). A subida ao Champaquí é uma das trilhas de trekking mais populares da Argentina e pode ser feita por diferentes vertentes. Do topo, com tempo bom, tem-se uma vista fantástica de toda a província de Córdoba. A flora é marcada por florestas de tabaquillo e vastas pastagens, que servem de área de caça para muitas aves de rapina, como o condor andino.",
      fr: "Le Cerro Champaquí, culminant à 2 790 mètres, est le point le plus élevé des Sierras de Córdoba et l'emblème de la région de Traslasierra. Il est situé dans la chaîne des Sierras Grandes et forme une frontière naturelle entre les vallées de Calamuchita et de Traslasierra. Le sommet se caractérise par un vaste plateau sur lequel se trouve un petit lac aux eaux cristallines qui a donné son nom à la montagne (Champaquí signifie l'eau dans l'herbe en langue comechingón). L'ascension du Champaquí est l'un des treks les plus populaires d'Argentine et peut être entreprise par différents versants. Par beau temps, le sommet offre une vue fantastique sur toute la province de Córdoba. La flore est marquée par des forêts de tabaquillos et de vastes prairies qui servent de terrain de chasse à de nombreux rapaces comme le condor des Andes.",
    },
