      hu: ["Córdoba tartomány legmagasabb hegye 2790 méteres magassággal.", "A név comechingón nyelven füves vizet jelent.", "A csúcsplatón egy kis tó található.", "Választóvonal a Calamuchita és a Traslasierra völgyek között.", "Közép-Argentína kedvelt trekking és hegyi turisztikai célpontja.", "Endemikus Polylepis erdők (tabaquillo) otthona.", "A csúcson egy kis menedékház található vészhelyzetek esetére."],
      ro: ["Altitudinea maximă este de 2.790 de metri", "Numele înseamnă 'apă pe vârf' în limba indigenă Comechingón", "Face parte din Parcul Natural Provincial Pampa de Achala", "Laguna de pe vârf îngheață frecvent în timpul iernii", "Este unul dintre cele mai vizitate puncte de trekking din Argentina", "Adăpostește monumentala statuie a lui Hristos pe vârful său", "Vegetația de la bază include păduri de 'Tabaquillo' (Polylepis australis)"],
      en: ["The maximum altitude is 2,790 meters.", "The name means 'water on the peak' in the indigenous Comechingón language.", "It is part of the Pampa de Achala Provincial Natural Park.", "The lagoon on the summit frequently freezes in winter.", "It is one of the most visited trekking spots in Argentina.", "Hosts the monumental statue of Christ on its summit.", "The vegetation at the base includes 'Tabaquillo' (Polylepis australis) forests."],
